  elseif o.area then
    local c = o.area.coords
    h = AddBlipForArea(c.x + 0.0, c.y + 0.0, c.z + 0.0, o.area.width + 0.0, o.area.height + 0.0)
    -- otherwise the rectangle rotates with the camera
    SetBlipRotation(h, rt.int(o.area.rotation or 0))
  else
    local c = o.coords
    if not c then error("Blip.create: one of coords, entity, radius or area is required", 2) end
    h = AddBlipForCoord(c.x + 0.0, c.y + 0.0, c.z + 0.0)
  end
  local b = T.wrap(h)
  if not b then return nil end
  if o.sprite then SetBlipSprite(h, o.sprite) end
  if o.color then SetBlipColour(h, o.color) end
  if o.scale then SetBlipScale(h, o.scale + 0.0) end
  if o.display then SetBlipDisplay(h, o.display) end
  if o.shortRange ~= nil then SetBlipAsShortRange(h, o.shortRange) end
  if o.category then SetBlipCategory(h, o.category) end
  if o.friendly ~= nil then SetBlipAsFriendly(h, o.friendly) end
  if o.route then SetBlipRoute(h, true) end
  if o.name then setters.name(b, o.name) end
  return b
end

end

return rt.finalize(T)
